// Pseudo-code sketch for online ICA (conceptual)
function onlineICA(X, state){
  const Ww = whiteningEMA(X, state.window); // rolling whitening
  let W = initializeDemixing(state);
  for (let b of freqBins){
    W[b] = onlineJointDiagonalization(W[b], X[b], state.forget);
  }
  const S = matMul(W, X);
